module {
  func.func @swap(%m: memref<2xi32>) {
    %c0 = arith.constant 0 : index
    %c1 = arith.constant 1 : index
    %a = memref.load %m[%c0] : memref<2xi32>
    %b = memref.load %m[%c1] : memref<2xi32>
    memref.store %b, %m[%c0] : memref<2xi32>
    memref.store %a, %m[%c1] : memref<2xi32>
    return
  }
}
